import React, { useState } from 'react';

export default function ManageSettings() {
  // UI එකේ පෙන්වන්න සකසන ලද ආයතනික තොරතුරු
  const [instituteName, setInstituteName] = useState('AuraPen Institute of Education');
  const [contactEmail, setContactEmail] = useState('info@aurapen.lk');
  const [contactPhone, setContactPhone] = useState('+94 11 234 5678');
  
  // Security States
  const [currentPassword, setCurrentPassword] = useState('');
  const [newPassword, setNewPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');

  // Toggles (පද්ධති ස්විචයන් - Presenter's Tricks)
  const [allowRegistration, setAllowRegistration] = useState(true);
  const [maintenanceMode, setMaintenanceMode] = useState(false);

  const handleSaveProfile = (e) => {
    e.preventDefault();
    alert("✅ Institute profile details updated successfully!");
  };

  const handleUpdatePassword = (e) => {
    e.preventDefault();
    if (!currentPassword || !newPassword || !confirmPassword) {
      alert("❌ Please fill all security fields!");
      return;
    }
    if (newPassword !== confirmPassword) {
      alert("❌ New passwords do not match!");
      return;
    }
    alert("🔒 Administrator security credentials updated successfully!");
    setCurrentPassword('');
    newPassword('');
    setConfirmPassword('');
  };

  return (
    <div style={{ padding: '10px 0', fontFamily: 'sans-serif', color: '#334155' }}>
      
      <h2 style={{ margin: '0 0 20px 0', color: '#1e293b', fontSize: '22px', fontWeight: 'bold' }}>
        ⚙️ System ConfigurationsDesk
      </h2>

      <div style={{ display: 'grid', gridTemplateColumns: '1.2fr 1fr', gap: '25px' }}>
        
        {/* LEFT COLUMN: GENERAL & INSTITUTIONAL SETTINGS */}
        <div style={{ display: 'flex', flexDirection: 'column', gap: '25px' }}>
          
          {/* Institute Profile Card */}
          <div style={styles.settingsCard}>
            <h3 style={styles.cardTitle}>🏫 Institution Profile & Branding</h3>
            <p style={styles.cardSubtitle}>Configure how your institute name appears on official PDF reports.</p>
            
            <form onSubmit={handleSaveProfile} style={styles.formGrid}>
              <div style={styles.inputGroup}>
                <label style={styles.label}>Institute Name</label>
                <input type="text" value={instituteName} onChange={(e) => setInstituteName(e.target.value)} style={styles.input} />
              </div>

              <div style={styles.inputGroup}>
                <label style={styles.label}>Official Contact Email</label>
                <input type="email" value={contactEmail} onChange={(e) => setContactEmail(e.target.value)} style={styles.input} />
              </div>

              <div style={styles.inputGroup}>
                <label style={styles.label}>Helpdesk Phone Number</label>
                <input type="text" value={contactPhone} onChange={(e) => setContactPhone(e.target.value)} style={styles.input} />
              </div>

              <button type="submit" style={styles.saveBtn}>Save Settings</button>
            </form>
          </div>

          {/* System Access Controls */}
          <div style={styles.settingsCard}>
            <h3 style={styles.cardTitle}>🌐 System Control Knobs</h3>
            <p style={styles.cardSubtitle}>Toggle foundational network behaviors for presentation parameters.</p>
            
            <div style={{ display: 'flex', flexDirection: 'column', gap: '15px', marginTop: '15px' }}>
              <div style={styles.toggleRow}>
                <div>
                  <strong style={{ fontSize: '14px', color: '#1e293b' }}>Allow Student Self-Registration</strong>
                  <p style={{ margin: '2px 0 0 0', fontSize: '12px', color: '#64748b' }}>If enabled, students can create accounts via login prompt.</p>
                </div>
                <input type="checkbox" checked={allowRegistration} onChange={(e) => setAllowRegistration(e.target.checked)} style={styles.checkbox} />
              </div>

              <div style={styles.toggleRow}>
                <div>
                  <strong style={{ fontSize: '14px', color: '#1e293b' }}>Server Maintenance Mode</strong>
                  <p style={{ margin: '2px 0 0 0', fontSize: '12px', color: '#64748b' }}>Locks down front-facing landing nodes for urgent backend syncs.</p>
                </div>
                <input type="checkbox" checked={maintenanceMode} onChange={(e) => setMaintenanceMode(e.target.checked)} style={styles.checkbox} />
              </div>
            </div>
          </div>

        </div>

        {/* RIGHT COLUMN: SECURITY SETTINGS */}
        <div style={styles.settingsCard}>
          <h3 style={styles.cardTitle}>🔒 Security & Authentication Desk</h3>
          <p style={styles.cardSubtitle}>Safely modify active system master administrator root credentials.</p>
          
          <form onSubmit={handleUpdatePassword} style={{ ...styles.formGrid, marginTop: '20px' }}>
            <div style={styles.inputGroup}>
              <label style={styles.label}>Current Master Password</label>
              <input type="password" placeholder="••••••••" value={currentPassword} onChange={(e) => setCurrentPassword(e.target.value)} style={styles.input} />
            </div>

            <div style={{ borderTop: '1px solid #f1f5f9', margin: '10px 0' }}></div>

            <div style={styles.inputGroup}>
              <label style={styles.label}>New Root Password</label>
              <input type="password" placeholder="Minimum 6 characters" value={newPassword} onChange={(e) => setNewPassword(e.target.value)} style={styles.input} />
            </div>

            <div style={styles.inputGroup}>
              <label style={styles.label}>Confirm New Password</label>
              <input type="password" placeholder="Retype new password" value={confirmPassword} onChange={(e) => setConfirmPassword(e.target.value)} style={styles.input} />
            </div>

            <button type="submit" style={{ ...styles.saveBtn, backgroundColor: '#1e293b' }}>Update Security Credentials</button>
          </form>
        </div>

      </div>

    </div>
  );
}

const styles = {
  settingsCard: { backgroundColor: '#ffffff', padding: '25px', borderRadius: '16px', boxShadow: '0 4px 12px rgba(0,0,0,0.02)', display: 'flex', flexDirection: 'column' },
  cardTitle: { margin: '0 0 5px 0', fontSize: '15px', color: '#1e293b', fontWeight: 'bold' },
  cardSubtitle: { margin: 0, fontSize: '12px', color: '#64748b', lineHeight: '1.4' },
  formGrid: { display: 'flex', flexDirection: 'column', gap: '15px', marginTop: '20px' },
  inputGroup: { display: 'flex', flexDirection: 'column', gap: '6px' },
  label: { fontSize: '13px', color: '#475569', fontWeight: '600' },
  input: { padding: '10px 12px', borderRadius: '8px', border: '1px solid #cbd5e1', outline: 'none', fontSize: '13px', backgroundColor: '#f8fafc' },
  saveBtn: { padding: '10px 15px', backgroundColor: '#15803d', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: 'bold', fontSize: '13px', marginTop: '5px', transition: 'background 0.2s' },
  toggleRow: { display: 'flex', justifyContent: 'space-between', alignItems: 'center', padding: '12px 15px', backgroundColor: '#f8fafc', borderRadius: '10px', border: '1px solid #f1f5f9' },
  checkbox: { width: '18px', height: '18px', cursor: 'pointer', accentColor: '#15803d' }
};
